  const [currentPlan, setCurrentPlan] = useState<'trial' | 'start' | 'plus' | 'master'>('trial');
  const [planExpiry, setPlanExpiry] = useState<string>('');
  const [subscriptionData, setSubscriptionData] = useState<any[]>([]);
