  const [tplImageFile, setTplImageFile] = useState<File | null>(null);
  const [tplImagePreview, setTplImagePreview] = useState('');
  const tplImageInputRef = React.useRef<HTMLInputElement>(null);
  const [detectingZones, setDetectingZones] = useState(false);



  // === Facebook Marketing API ===
  const [fbCampaigns, setFbCampaigns] = useState<any[]>([]);
  const [selectedCreative, setSelectedCreative] = useState<any>(null);
  const [fbInsights, setFbInsights] = useState<any>(null);
  const [fbLoading, setFbLoading] = useState(false);
  const [fbError, setFbError] = useState<string | null>(null);
  const [analyticsPeriod, setAnalyticsPeriod] = useState<'week' | 'month'>('week');
  const [insightsLastUpdated, setInsightsLastUpdated] = useState<Date | null>(null);
  const [insightsSecondsAgo, setInsightsSecondsAgo] = useState(0);
  const analyticsExportRef = React.useRef<HTMLDivElement>(null);
  const [exportingAnalytics, setExportingAnalytics] = useState(false);
  const [aiInsights, setAiInsights] = useState<{ message: string; metric: string; confidence: string }[] | null>(null);
  const [aiInsightsLoading, setAiInsightsLoading] = useState(false);
  const isNoMetaApiError = (msg: string) => msg?.toLowerCase().includes('no tienes credenciales') || msg?.toLowerCase().includes('meta ads configuradas') || msg?.toLowerCase().includes('faltan credenciales');
  const loadFbCampaigns = async () => { setFbLoading(true); setFbError(null); try { const r = await authFetch('/api/panel/facebook/campaigns?date_preset=last_30d'); const d = await r.json(); if(d.success) setFbCampaigns(d.campaigns||[]); else { if(isNoMetaApiError(d.error)) { setShowMetaNoApiModal(true); } else { setFbError(d.error||'Error'); } } } catch(e:any){ if(isNoMetaApiError(e.message)) { setShowMetaNoApiModal(true); } else { setFbError(e.message); } } finally{setFbLoading(false)} };
  const loadAiInsights = async (insightsData: any) => {
    setAiInsightsLoading(true);
    try {
      const r = await authFetch('/api/panel/campaigns/insights', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ kpis: insightsData.kpis, platformBreakdown: insightsData.platformBreakdown, topCreatives: insightsData.topCreatives }),
      });
      const d = await r.json();
      if (d.insights) setAiInsights(d.insights); else setAiInsights(null);
    } catch (e: any) {
      setAiInsights(null);
    } finally {
      setAiInsightsLoading(false);
    }
  };
  const loadFbInsights = async (periodOverride?: 'week' | 'month') => {
    setFbLoading(true); setFbError(null);
    try {
      const period = periodOverride || analyticsPeriod;
      const r = await authFetch(`/api/panel/facebook/insights?period=${period}`);
      const d = await r.json();
      if (d.success) {
        setFbInsights(d);
        setInsightsLastUpdated(new Date());
        loadAiInsights(d);
      } else {
        if (isNoMetaApiError(d.error)) { setShowMetaNoApiModal(true); } else { setFbError(d.error || 'Error'); }
      }
    } catch (e: any) {
      if (isNoMetaApiError(e.message)) { setShowMetaNoApiModal(true); } else { setFbError(e.message); }
    } finally { setFbLoading(false); }
  };

  // Refresco automatico cada 60s mientras se esta viendo la pestaña de
  // Analiticas y la pagina esta visible (se pausa si el usuario cambia de
  // pestaña del navegador, para no gastar cuota de la API sin necesidad).
  useEffect(() => {
    if (activeTab !== 'campaigns' || campaignSubTab !== 'analytics' || !fbInsights) return;
    const interval = setInterval(() => {
      if (document.visibilityState === 'visible') loadFbInsights();
    }, 60000);
    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab, campaignSubTab, !!fbInsights, analyticsPeriod]);

  // Contador de "hace X segundos" para el indicador de ultima actualizacion
  useEffect(() => {
    if (!insightsLastUpdated) return;
    const tick = () => setInsightsSecondsAgo(Math.floor((Date.now() - insightsLastUpdated.getTime()) / 1000));
    tick();
    const interval = setInterval(tick, 1000);
    return () => clearInterval(interval);
  }, [insightsLastUpdated]);

  const handleAnalyticsPeriodChange = (period: 'week' | 'month') => {
    setAnalyticsPeriod(period);
    if (fbInsights) loadFbInsights(period);
  };

  // Exporta todo el panel de metricas (KPIs, alertas, grafico, ROI,
  // plataformas y creatividades) como una sola imagen PNG de alta
  // resolucion, tal como se ve en pantalla.
  const handleExportAnalyticsImage = async () => {
    if (!analyticsExportRef.current || exportingAnalytics) return;
    setExportingAnalytics(true);
    try {
      if (document.fonts?.ready) await document.fonts.ready;
      const html2canvas = (await import('html2canvas-pro')).default;
      const canvas = await html2canvas(analyticsExportRef.current, {
        backgroundColor: '#f8f9ff',
        scale: 2,
        useCORS: true,
        logging: false,
        onclone: (clonedDoc: Document) => {
          // Los iconos de Material Symbols son ligaduras de fuente (el texto
          // real detras es "error", "warning", etc.) — html2canvas dibuja
          // texto caracter por caracter en un canvas 2D y no puede resolver
          // ligaduras OpenType, asi que sale el nombre literal en vez del
          // glifo. Los ocultamos para el export en vez de mostrar texto roto.
          clonedDoc.querySelectorAll('.material-symbols-outlined').forEach((el) => {
            (el as HTMLElement).style.visibility = 'hidden';
          });
        },
      });
      const link = document.createElement('a');
      const dateStr = new Date().toISOString().split('T')[0];
      link.download = `rifx-analiticas-${analyticsPeriod}-${dateStr}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
      setToast({ message: language === 'en' ? 'Report image downloaded' : 'Imagen del reporte descargada', type: 'success' });
    } catch (e: any) {
      console.error('[EXPORT ANALYTICS IMAGE]', e);
      setToast({ message: language === 'en' ? 'Could not export the image' : 'No se pudo exportar la imagen', type: 'error' });
    } finally {
      setExportingAnalytics(false);
    }
  };

  // delta null = periodo anterior sin datos suficientes para comparar
  const formatDelta = (delta: number | null, lang: string): { text: string; positive: boolean | null } => {
    if (delta === null) return { text: lang === 'en' ? 'Not enough data' : 'Datos insuficientes', positive: null };
    return { text: `${delta > 0 ? '+' : ''}${delta}%`, positive: delta >= 0 };
  };

  const formatCompact = (raw: string | number): string => {
    const n = typeof raw === 'string' ? parseInt(raw, 10) : raw;
    if (!n || isNaN(n)) return '0';
    if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
    return n.toLocaleString();
  };

  // Sparkline real a partir de dailyInsights (no datos inventados)
  const buildSparkline = (metric: 'impressions' | 'clicks' | 'conversionRate'): number[] => {
    const daily = fbInsights?.dailyInsights as any[] | undefined;
    if (!daily || daily.length === 0) return [];
    const values = daily.map(d => {
      if (metric === 'conversionRate') {
        const clicks = parseInt(d.clicks || '0', 10);
        const conv = parseInt(d.conversions || '0', 10);
        return clicks > 0 ? (conv / clicks) * 100 : 0;
      }
      return parseInt(d[metric] || '0', 10);
    });
    const max = Math.max(...values, 1);
    return values.map(v => Math.max(4, Math.round((v / max) * 100)));
  };
  const toggleFbCampaign = async (id:string, status:string) => { const s = status==='ACTIVE'?'PAUSED':'ACTIVE'; try { const r = await authFetch('/api/panel/facebook/campaigns',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({campaign_id:id,status:s})}); const d = await r.json(); if(d.success) loadFbCampaigns(); else setToast({ message: d.error, type: 'error' }); } catch(e:any){setToast({ message: e.message, type: 'error' })} };
  const deleteFbCampaign = async (id:string) => { if(!confirm('Eliminar esta campaña?')) return; try { const r = await authFetch('/api/panel/facebook/campaigns?campaign_id='+id,{method:'DELETE'}); const d = await r.json(); if(d.success) loadFbCampaigns(); else setToast({ message: d.error, type: 'error' }); } catch(e:any){setToast({ message: e.message, type: 'error' })} };
  const [fbPublishing, setFbPublishing] = useState(false);
  const [showMetaPermissionsModal, setShowMetaPermissionsModal] = useState(false);
  const [showMetaNoApiModal, setShowMetaNoApiModal] = useState(false);
  const [showWhatsAppNotLinkedModal, setShowWhatsAppNotLinkedModal] = useState(false);

  // Sube un archivo (imagen o video) a R2 y devuelve su URL firmada de descarga.
  const uploadFileToR2 = async (file: File | Blob, fallbackName: string): Promise<string> => {
    const fileName = file instanceof File ? file.name : fallbackName;
    const fileType = file.type || 'application/octet-stream';

    const getUrlRes = await authFetch(`/api/panel/social/storage?action=upload&filename=${encodeURIComponent(fileName)}&contentType=${encodeURIComponent(fileType)}&size=${file.size}`);
    if (!getUrlRes.ok) {
      const errData = await getUrlRes.json();
      throw new Error(errData.error || 'Error al obtener URL de subida de almacenamiento.');
    }
    const { uploadUrl, key } = await getUrlRes.json();

    const uploadRes = await fetch(uploadUrl, { method: 'PUT', headers: { 'Content-Type': fileType }, body: file });
    if (!uploadRes.ok) {
      throw new Error('Error al subir el archivo al almacenamiento.');
    }

    const signRes = await authFetch(`/api/panel/social/storage?action=sign&key=${encodeURIComponent(key)}`);
    if (!signRes.ok) {
      const errData = await signRes.json();
      throw new Error(errData.error || 'Error al firmar la URL del archivo.');
    }
    const { signedUrl } = await signRes.json();
    return signedUrl;
  };

  const publishToFacebook = async () => {
    const totalCreatives = (finalUploadedImage ? 1 : 0) + extraCreativeAssets.length;
    if (!finalUploadedImage || totalCreatives < MAX_CREATIVE_ASSETS) {
      setToast({
        message: language === 'en'
          ? `Select ${MAX_CREATIVE_ASSETS} images or videos to publish (${totalCreatives}/${MAX_CREATIVE_ASSETS} so far)`
          : `Seleccioná ${MAX_CREATIVE_ASSETS} imágenes o videos para publicar (llevás ${totalCreatives}/${MAX_CREATIVE_ASSETS})`,
        type: 'info'
      });
      return;
    }
    if (adCountries.length === 0) {
      setToast({ message: language === 'en' ? 'Select at least one target country' : 'Selecciona al menos un país destino', type: 'info' }); 
      return; 
    }
    setFbPublishing(true);
    try {
      // Subir la imagen primero si es necesario
      setToast({ message: language === 'en' ? 'Uploading ad image...' : 'Subiendo imagen de publicidad...', type: 'info' });
      
      let imageUrl = '';
      if (finalUploadedImage.startsWith('http://') || finalUploadedImage.startsWith('https://')) {
        imageUrl = finalUploadedImage;
      } else {
        let fileToUpload: File | Blob;
        let fileName = 'ad-image.png';
        let fileType = 'image/png';
        
        if (campaignImage instanceof File) {
          fileToUpload = campaignImage;
          fileName = campaignImage.name;
          fileType = campaignImage.type;
        } else if (finalUploadedImage.startsWith('data:')) {
          const arr = finalUploadedImage.split(',');
          const mime = arr[0].match(/:(.*?);/)?.[1] || 'image/png';
          const bstr = atob(arr[1]);
          let n = bstr.length;
          const u8arr = new Uint8Array(n);
          while (n--) {
            u8arr[n] = bstr.charCodeAt(n);
          }
          fileToUpload = new Blob([u8arr], { type: mime });
          fileType = mime;
          const ext = mime.split('/')[1] || 'png';
          fileName = `generated-banner.${ext}`;
        } else if (finalUploadedImage.startsWith('blob:')) {
          try {
            const response = await fetch(finalUploadedImage);
            fileToUpload = await response.blob();
            fileType = fileToUpload.type || 'image/png';
            const ext = fileType.split('/')[1] || 'png';
            fileName = `blob-image.${ext}`;
          } catch (err) {
            console.error('Error fetching blob from object URL:', err);
            throw new Error('Error al leer el archivo temporal de la imagen.');
          }
        } else {
          throw new Error('Formato de imagen no soportado.');
        }

        // 1. Obtener URL firmada de subida de R2
        const getUrlRes = await authFetch(`/api/panel/social/storage?action=upload&filename=${encodeURIComponent(fileName)}&contentType=${encodeURIComponent(fileType)}&size=${fileToUpload.size}`);
        if (!getUrlRes.ok) {
          const errData = await getUrlRes.json();
          throw new Error(errData.error || 'Error al obtener URL de subida de almacenamiento.');
        }
        const { uploadUrl, key } = await getUrlRes.json();

        // 2. Subir el archivo usando PUT
        const uploadRes = await fetch(uploadUrl, {
          method: 'PUT',
          headers: { 'Content-Type': fileType },
          body: fileToUpload
        });
        if (!uploadRes.ok) {
          throw new Error('Error al subir el archivo de imagen al almacenamiento.');
        }

        // 3. Obtener URL firmada de descarga
        const signRes = await authFetch(`/api/panel/social/storage?action=sign&key=${encodeURIComponent(key)}`);
        if (!signRes.ok) {
          const errData = await signRes.json();
          throw new Error(errData.error || 'Error al firmar la URL de la imagen.');
        }
        const { signedUrl } = await signRes.json();
        imageUrl = signedUrl;
      }

      // Subir las creatividades adicionales (imagen/video) para los otros
      // anuncios del conjunto — la principal (imageUrl) ya se subio arriba.
      let creativeAssets: Array<{ url: string; type: 'image' | 'video' }> = [{ url: imageUrl, type: 'image' }];
      if (extraCreativeAssets.length > 0) {
        setToast({ message: language === 'en' ? `Uploading ${extraCreativeAssets.length} more creatives...` : `Subiendo ${extraCreativeAssets.length} creatividades más...`, type: 'info' });
        const uploadedExtras = await Promise.all(extraCreativeAssets.map(async (asset) => ({
          url: await uploadFileToR2(asset.file, `extra-${asset.type}-${Date.now()}`),
          type: asset.type,
        })));
        creativeAssets = [...creativeAssets, ...uploadedExtras];
      }

      setToast({ message: language === 'en' ? 'Publishing campaign to Meta...' : 'Publicando campaña en Meta...', type: 'info' });

      const caption = campaignResult?.caption || adDescription || campaignDesc || '';
      const hashtagsBlock = campaignResult?.hashtags ? '\n' + campaignResult.hashtags : '';
      const cfg = campaignResult?.campaign_config || {};
      const aud = campaignResult?.target_audience || {};

      // Variantes de texto para poder publicar minimo 6 anuncios por conjunto
      // (A/B testing de copy) — usa el hook principal + variantes generadas
      // por IA. El backend rellena hasta 6 si vienen menos.
      const hooks = [campaignResult?.hook, ...(campaignResult?.hook_variants || [])].filter(Boolean);
      const trimmedCaption = caption.trim();
      const messageVariants = (hooks.length > 0 ? hooks : [caption]).map((hook: string) => {
        const trimmedHook = (hook || '').trim();
        // Evita texto duplicado cuando el hook generado por la IA ya es
        // igual al caption o ya viene incluido al inicio del caption.
        if (!trimmedHook || trimmedHook === trimmedCaption || trimmedCaption.startsWith(trimmedHook)) {
          return `${trimmedCaption}${hashtagsBlock}`.trim();
        }
        return `${trimmedHook}\n\n${trimmedCaption}${hashtagsBlock}`.trim();
      });

      // Validate objective — cada objetivo de negocio usa el objetivo de
      // campaña de Meta que mejor le sirve, en vez de dejarlo a lo que
      // sugiera la IA:
      //  - "Atraer clientes a mi Local Físico" -> Interacción (ENGAGEMENT):
      //    maximiza likes/comentarios/seguidores de la Página, que es la
      //    señal que alimenta el público personalizado de remarketing.
      //  - "Recibir mensajes y vender por WhatsApp" -> Ventas (SALES): el
      //    objetivo apunta directo a la conversión (venta) por chat, ya que
      //    el paso anterior recolecta el numero de WhatsApp del negocio.
      //  - "Vender desde mi Página Web o tienda online" -> Ventas (SALES):
      //    igual, apunta a conversión, esta vez con destino la página/tienda
      //    web que se pidió en el paso anterior.
      // El público de remarketing de la fase 2 (page_engaged,
      // page_post_interaction, page_liked, page_cta_clicked) se arma igual
      // para los 3 objetivos — no depende del objetivo elegido.
      const validObjectives = ['OUTCOME_LEADS', 'OUTCOME_SALES', 'OUTCOME_ENGAGEMENT', 'OUTCOME_AWARENESS', 'OUTCOME_TRAFFIC', 'OUTCOME_APP_PROMOTION'];
      const objective = agentGoal === 'local'
        ? 'OUTCOME_ENGAGEMENT'
        : (agentGoal === 'whatsapp' || agentGoal === 'web')
        ? 'OUTCOME_SALES'
        : (validObjectives.includes(cfg.objective) ? cfg.objective : 'OUTCOME_TRAFFIC');

      const r = await authFetch('/api/panel/facebook/publish', {
        method: 'POST',
        headers: {'Content-Type':'application/json'},
        body: JSON.stringify({
          campaign_name: (campaignResult?.hook || caption || 'RIFX Campaign').substring(0, 50),
          message: caption + hashtagsBlock,
          message_variants: messageVariants,
          daily_budget: dailyBudget * 100, // convert to cents
          duration_days: campaignDurationDays,
          language,
          objective,
          sales_destination: agentGoal === 'whatsapp' ? 'whatsapp' : agentGoal === 'web' ? 'web' : undefined,
          targeting_mode: 'simple', // Advantage+ audience — Meta optimiza siempre
          countries: adCountries,
          custom_locations: adLocations.map(l => ({ lat: l.lat, lng: l.lng, radius: l.radius })),
          age_min: aud.age_min || 18,
          age_max: aud.age_max || 65,
          link_url: 'https://rifx.online',
          image_url: imageUrl,
          creative_assets: creativeAssets,
          call_to_action: cfg.call_to_action || 'LEARN_MORE',
          status: 'PAUSED'
        })
      });
      const d = await r.json();
      if (d.success) {
        const phasesMsg = d.phases === 2
          ? (language === 'en' ? ` • 2 phases (learning + remarketing)` : ` • 2 fases (aprendizaje + remarketing)`)
          : '';
        const adsMsg = d.ads_created ? ` • ${d.ads_created} ${language === 'en' ? 'ads' : 'anuncios'}` : '';
        setToast({ message: language === 'en'
          ? `Campaign published! Advantage+ Audience${adsMsg}${phasesMsg} • PAUSED`
          : `¡Campaña publicada! Audiencia Advantage+${adsMsg}${phasesMsg} • PAUSADA`,
          type: 'success'
        });
        loadFbCampaigns();
        setCampaignSubTab('campaigns');
      } else {
        // Check if it's a "no API configured" error
        if (isNoMetaApiError(d.error)) {
          setShowMetaNoApiModal(true);
        } else {
          const isPermError = d.step === 'creative' && (
            d.error?.toLowerCase().includes('permiso') ||
            d.error?.toLowerCase().includes('perfil') ||
            d.error?.toLowerCase().includes('permission') ||
            d.error?.toLowerCase().includes('profile') ||
            d.error?.toLowerCase().includes('instagram')
          );
          const isWhatsAppNotLinkedError = d.error?.toLowerCase().includes('vinculada a una cuenta de whatsapp') ||
            d.error?.toLowerCase().includes('not linked to a whatsapp');
          if (isWhatsAppNotLinkedError) {
            setShowWhatsAppNotLinkedModal(true);
          } else if (isPermError) {
            setShowMetaPermissionsModal(true);
          } else {
            setToast({ message: `Error (${d.step || '?'}): ${d.error || 'Error desconocido'}`, type: 'error' });
          }
        }
      }
    } catch(e:any) { 
      if (isNoMetaApiError(e.message)) {
        setShowMetaNoApiModal(true);
      } else {
        setToast({ message: 'Error de conexión: ' + e.message, type: 'error' }); 
      }
    } finally { 
      setFbPublishing(false); 
    }
  };


  const handleGenerateCampaign = async () => {
    if (!campaignDesc && !campaignTitle) return;
    setIsGeneratingCampaign(true);
    setCampaignResult(null);
    try {
      const res = await authFetch('/api/panel/campaigns/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ description: campaignDesc, title: campaignTitle, daily_budget: dailyBudget, has_reference_image: !!campaignImagePreview, has_product_image: !!productImagePreview })
      });
      const data = await res.json();
      if (data.success) {
        setCampaignResult(data.campaign);
      } else {
        setToast({ message: data.error || 'Error generating campaign', type: 'error' });
      }
    } catch (e) {
      console.error(e);
      setToast({ message: 'Error connecting to server', type: 'error' });
    } finally {
      setIsGeneratingCampaign(false);
    }
  };

