                  {fbCampaigns.length > 0 && <span className="text-sm text-[#006947] bg-[#006947]/10 px-3 py-1 rounded-lg font-semibold">{fbCampaigns.length} {language === 'en' ? 'campaigns loaded' : 'campañas cargadas'}</span>}
